"use client";

import Link from "next/link";
import * as React from "react";
import {
    ChevronLeft,
    Ellipsis,
    Plus,
    Search,
    SlidersHorizontal,
} from "lucide-react";
import { PendingAsset } from "@/components/pages/studio/pending-asset";
import { BRAND_LOGO_PATH } from "@/components/pages/studio/studio-data";
import styles from "./portfolio-landing.module.css";

type MediaType = "image" | "video" | "model";

type AlbumCardKind = "default";

interface IAssetApiItem {
    id: number;
    title: string | null;
    fileName: string;
    relativePath: string;
    mediaType: MediaType;
    thumbnailPath: string | null;
}

interface IAlbumApiItem {
    id: number;
    name: string;
    thumbnailPath: string | null;
    assetCount: number;
}

interface IAlbumCard {
    id: string;
    name: string;
    previewUrl?: string;
    href?: string;
    kind: AlbumCardKind;
}

function getAssetFileUrl(relativePath: string) {
    return `/api/assets/file?path=${encodeURIComponent(relativePath)}`;
}

function getAssetPreviewUrl(item: IAssetApiItem) {
    if (item.thumbnailPath) {
        return getAssetFileUrl(item.thumbnailPath);
    }

    if (item.mediaType === "image") {
        return getAssetFileUrl(item.relativePath);
    }

    if (item.mediaType === "video") {
        return "/images/homeicon2.png";
    }

    return "/images/homeicon3.png";
}

export default function PortfolioLandingPage() {
    const [assets, setAssets] = React.useState<IAssetApiItem[]>([]);
    const [albums, setAlbums] = React.useState<IAlbumApiItem[]>([]);
    const [isLoading, setIsLoading] = React.useState(true);
    const [loadError, setLoadError] = React.useState<string | null>(null);
    const [saveError, setSaveError] = React.useState<string | null>(null);
    const [isSavingAlbum, setIsSavingAlbum] = React.useState(false);
    const [searchQuery, setSearchQuery] = React.useState("");
    const [isManageMode, setIsManageMode] = React.useState(false);
    const [isCreateDialogOpen, setIsCreateDialogOpen] = React.useState(false);
    const [albumName, setAlbumName] = React.useState("");

    React.useEffect(() => {
        const controller = new AbortController();

        const loadPortfolioData = async () => {
            setIsLoading(true);
            setLoadError(null);
            setSaveError(null);

            try {
                const [assetsResponse, albumsResponse] = await Promise.all([
                    fetch("/api/assets?albumId=default", {
                        signal: controller.signal,
                    }),
                    fetch("/api/albums", {
                        signal: controller.signal,
                    }),
                ]);

                if (!assetsResponse.ok || !albumsResponse.ok) {
                    throw new Error("加载作品册失败");
                }

                const assetsData = await assetsResponse.json() as { assets?: IAssetApiItem[] };
                const albumsData = await albumsResponse.json() as { albums?: IAlbumApiItem[] };
                setAssets(assetsData.assets || []);
                setAlbums(albumsData.albums || []);
            } catch (error) {
                if (controller.signal.aborted) {
                    return;
                }

                setLoadError(error instanceof Error ? error.message : "加载作品册失败");
                setAssets([]);
                setAlbums([]);
            } finally {
                if (!controller.signal.aborted) {
                    setIsLoading(false);
                }
            }
        };

        void loadPortfolioData();

        return () => {
            controller.abort();
        };
    }, []);

    const cards = React.useMemo<IAlbumCard[]>(() => {
        const customCards = albums.map((album) => ({
            id: String(album.id),
            name: album.name,
            previewUrl:
                album.assetCount > 0 && album.thumbnailPath
                    ? getAssetFileUrl(album.thumbnailPath)
                    : "/images/相册-无图片.png",
            href: `/portfolio/album/${album.id}`,
            kind: "default" as const,
        }));

        return [
            {
                id: "default",
                name: "默认作品",
                previewUrl: "/images/默认作品.png",
                href: "/portfolio/default",
                kind: "default",
            },
            ...customCards,
        ];
    }, [albums]);

    const visibleCards = React.useMemo(() => {
        if (!searchQuery.trim()) {
            return cards;
        }

        const keyword = searchQuery.trim().toLowerCase();
        return cards.filter((card) => card.name.toLowerCase().includes(keyword));
    }, [cards, searchQuery]);

    const nameLength = albumName.trim().length;

    const handleOpenCreateDialog = () => {
        setAlbumName("");
        setIsCreateDialogOpen(true);
    };

    const handleCloseCreateDialog = () => {
        setIsCreateDialogOpen(false);
        setAlbumName("");
    };

    const handleSaveAlbum = async () => {
        const normalizedName = albumName.trim();
        if (!normalizedName || isSavingAlbum) {
            return;
        }

        setIsSavingAlbum(true);
        setSaveError(null);

        try {
            const response = await fetch("/api/albums", {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                },
                body: JSON.stringify({ name: normalizedName }),
            });

            const data = await response.json() as {
                ok?: boolean;
                error?: string;
                album?: IAlbumApiItem;
            };

            if (!response.ok || !data.ok || !data.album) {
                throw new Error(data.error || "新建作品册失败");
            }

            setAlbums((prev) => [data.album as IAlbumApiItem, ...prev]);
            handleCloseCreateDialog();
        } catch (error) {
            setSaveError(error instanceof Error ? error.message : "新建作品册失败");
        } finally {
            setIsSavingAlbum(false);
        }
    };

    return (
        <main className={styles.page}>
            <header className={styles.topBar}>
                <Link
                    href="/"
                    className={styles.backButton}
                    aria-label="返回首页"
                    onClick={() => {
                        console.log("[Portfolio Landing Back] click", {
                            currentUrl: window.location.href,
                            targetUrl: "/",
                            historyLength: window.history.length,
                        });
                    }}
                >
                    <ChevronLeft size={22} />
                </Link>
                <label className={styles.searchBar}>
                    <Search size={20} className={styles.searchIcon} />
                    <input
                        value={searchQuery}
                        onChange={(event) => setSearchQuery(event.target.value)}
                        placeholder="输入作品册名称搜索..."
                        aria-label="搜索作品册"
                    />
                </label>
                <div className={styles.brandWrap}>
                    <PendingAsset
                        src={BRAND_LOGO_PATH}
                        alt="飞思玖·璇玑AI"
                        className={styles.brandLogo}
                        fit="contain"
                    />
                </div>
            </header>

            <section className={styles.panel}>
                <div className={styles.sectionHeader}>
                    <h1 className={styles.title}>作品册</h1>

                    <div className={styles.actions}>
                        <button
                            type="button"
                            className={styles.createButton}
                            onClick={handleOpenCreateDialog}
                        >
                            <Plus size={18} />
                            <span>新建作品册</span>
                        </button>
                        <button
                            type="button"
                            className={`${styles.manageButton} ${isManageMode ? styles.manageButtonActive : ""}`}
                            onClick={() => setIsManageMode((value) => !value)}
                        >
                            <SlidersHorizontal size={22} />
                            <span>管理</span>
                        </button>
                    </div>
                </div>

                {loadError ? <p className={styles.inlineMessage}>{loadError}</p> : null}
                {saveError ? <p className={styles.inlineMessage}>{saveError}</p> : null}
                {isLoading ? <p className={styles.inlineMessage}>加载中...</p> : null}

                {visibleCards.length > 0 ? (
                    <div className={styles.grid}>
                        {visibleCards.map((card) => {
                            const isPlaceholderCover = card.previewUrl === "/images/相册-无图片.png";
                            const cardContent = (
                                <>
                                    <div className={styles.cover}>
                                        <div className={styles.defaultCover}>
                                            <img
                                                src={card.previewUrl}
                                                alt="默认作品"
                                                className={isPlaceholderCover ? styles.placeholderPreview : undefined}
                                            />
                                        </div>
                                    </div>

                                    <div className={styles.cardFooter}>
                                        <span className={styles.cardName}>{card.name}</span>
                                        <span
                                            className={styles.moreButton}
                                            aria-hidden="true"
                                        >
                                            <Ellipsis size={18} />
                                        </span>
                                    </div>
                                </>
                            );

                            return (
                                <Link
                                    key={card.id}
                                    href={card.href || "/portfolio/default"}
                                    className={`${styles.card} ${styles.defaultCard} ${isManageMode ? styles.cardManage : ""}`}
                                >
                                    {cardContent}
                                </Link>
                            );
                        })}
                    </div>
                ) : (
                    <div
                        className={styles.emptyState}
                        role="status"
                        aria-live="polite"
                    >
                        <p className={styles.emptyStateText}>没有找到匹配的作品册</p>
                        <button
                            type="button"
                            className={styles.emptyStateAction}
                            onClick={() => setSearchQuery("")}
                        >
                            清空搜索
                        </button>
                    </div>
                )}
            </section>

            {isCreateDialogOpen ? (
                <div
                    className={styles.dialogOverlay}
                    role="presentation"
                    onClick={(event) => {
                        if (event.target === event.currentTarget) {
                            handleCloseCreateDialog();
                        }
                    }}
                >
                    <div
                        className={styles.dialog}
                        role="dialog"
                        aria-modal="true"
                        aria-label="新建作品册"
                    >
                        <div className={styles.dialogHeader}>
                            <h2 className={styles.dialogTitle}>新建作品册</h2>
                        </div>

                        <div className={styles.dialogField}>
                            <label htmlFor="portfolio-album-name" className={styles.dialogLabel}>
                                作品册名称
                            </label>
                            <div className={styles.dialogInputWrap}>
                                <input
                                    id="portfolio-album-name"
                                    value={albumName}
                                    onChange={(event) => setAlbumName(event.target.value.slice(0, 20))}
                                    placeholder="请输入"
                                    className={styles.dialogInput}
                                    autoFocus
                                />
                                <span className={styles.dialogCounter}>{nameLength}/20</span>
                            </div>
                        </div>

                        <div className={styles.dialogFooter}>
                            <button
                                type="button"
                                className={styles.dialogCancelBtn}
                                onClick={handleCloseCreateDialog}
                            >
                                取消
                            </button>
                            <button
                                type="button"
                                className={styles.dialogSaveBtn}
                                onClick={() => {
                                    void handleSaveAlbum();
                                }}
                                disabled={!albumName.trim() || isSavingAlbum}
                            >
                                {isSavingAlbum ? "保存中..." : "确定"}
                            </button>
                        </div>
                    </div>
                </div>
            ) : null}
        </main>
    );
}